			function checkDate() {
			    
			    var startDate = app.lookup("cmnDaterangePickerConDate").startDate;
			    var endDate = app.lookup("cmnDaterangePickerConDate").endDate;
			    
			    var startYm = startDate.substr(0, 6);
			    var endYm = endDate.substr(0, 6);
			    var ii = 0;
			    var ym = startYm;
			    for(ii = 1; Number(ym) < Number(endYm); ii++) {
			        if ( ii == 1 ) continue;
			        var mm = ym.substr(4, 2);
			        if ( mm == 12 ) ym = (Number(ym.substr(0, 4))+1)+'01';
			        else ym = (Number(ym.substr(0, 6))+1)+'';
			        if ( ii > 12 ) {
			            util.Msg.notify(app, "WRN-M012");   //기간을 확인해 주세요.
			            return false;
			        }
			    }
			    return true;

			}

			function doCreateTab() {
			    console.log("1 doCreateTab : 0 ");
			    
			    var startDate = app.lookup("cmnDaterangePickerConDate").startDate;
			    var endDate = app.lookup("cmnDaterangePickerConDate").endDate;
			    

			    var tabFolder = app.lookup('tab');
			    var tabItems = tabFolder.getTabItems();
			    for (var i = 1; i < tabItems.length; i++) {
			        tabFolder.removeTabItem(tabItems[i]);
			    }
			    
			    var aaa = function(i, startm, endm, years) {
			        var _id = years + ( i<10?'0'+i:i );        
			        var voTabItem = new cpr.controls.TabItem();
			        voTabItem.text = years + '년 ' + i + '월';
			        var embeddedApp_1 = new cpr.controls.EmbeddedApp("embapp_" + _id);
			        cpr.core.App.load("app/couns/stats/dscsnstats/monthlyStatsDetail", function(app2) {
			            if (app2) {
			                embeddedApp_1.app = app2;
			                voTabItem.content = embeddedApp_1;
			                voTabItem.id = 'tabItem' + _id;
			                voTabItem.userAttr("yearMonth", _id);
			                tabFolder.addTabItem(voTabItem);                
			                i++;
			                if (i <= endm) {
			                    aaa(i, startm, endm, years);
			                }else{
			                    tabFolder.setSelectedTabItem(tabFolder.getTabItems()[0]);
			                }
			            }
			        });
			    }
			    
			    if (startDate.substr(0, 4) == endDate.substr(0, 4)) {
			        var startm = startDate.substr(4, 2) - 0;
			        var endm = endDate.substr(4, 2) - 0;
			        var i = startm;
			        aaa(i, startm, endm, startDate.substr(0, 4));
			    } else {
			        var startm = startDate.substr(4, 2) - 0;
			        var endm = endDate.substr(4, 2) - 0;
			        var i = startm;
			        aaa(i, startm, '12', startDate.substr(0, 4));
			        i = 1;
			        aaa(i, '1', endm, endDate.substr(0, 4));        
			    }
			}

