			        app.lookup('embapp_' + _id).setAppProperty("writeType", null);
			        app.lookup('embapp_' + _id).setAppProperty("memType", null);
			        app.lookup('embapp_' + _id).setAppProperty("gender", null);
			        app.lookup('embapp_' + _id).setAppProperty("end", null);
